const resp = $.steps.fetchTranscript.response || {};
const sentences = resp.sentences || [];
const pagination = resp.pagination || {};

const speakers = [...new Set(sentences.map(s => s.speaker).filter(Boolean))];

const transcript = sentences.map(s => ({
  speaker: s.speaker || 'Unknown',
  timestamp: s.timestamp || '',
  text: s.transcript || ''
}));

return {
  meetingId: resp.meeting_id || $.input.meetingId,
  sentences: transcript,
  totalSentences: transcript.length,
  speakers,
  nextCursor: pagination.next_cursor || null,
  previousCursor: pagination.previous_cursor || null,
  summary: `Retrieved ${transcript.length} transcript sentence${transcript.length === 1 ? '' : 's'} from ${speakers.length} speaker${speakers.length === 1 ? '' : 's'}`
};
